import type { CandidateSummary, GenerationResult } from "./api-types";
import fittings from "./fittings.json";
import { fittingIcons } from "./fitting-icons";

/**
 * Real Baste runs, recorded on fal for each base persona, so the static site
 * can show what a run produces without a server: every judged QD candidate,
 * and the final suite (hero, background, icons, ambient loop) with its scores.
 * Generated by `baste generate <persona> --config media/baste-demo/runs/…`.
 */
export interface RecordedRun {
  persona: string;
  model: string;
  judge: string;
  generations: number;
  durationMs: number;
  candidates: CandidateSummary[];
  /** The hero brief as the engine first drafts it, before the search moves its variation lines. */
  brief: string;
  /** The brief the final cut was generated from, after evolution. */
  evolved: string;
  /** The judge's top candidate, also exported at full size. */
  best: { index: number; src: string };
}

/** Bundled per persona, so each recorded run is only loaded when it is replayed.
 *  Outside Vite (the node test runner) there is no glob, and no runs to replay. */
const RUNS: Record<string, () => Promise<RecordedRun>> = typeof import.meta.glob === "function"
  ? import.meta.glob<RecordedRun>("./runs/*.json", { import: "default" })
  : {};

export function hasRecordedRun(personaId: string): boolean {
  return `./runs/${personaId}.json` in RUNS;
}

export function loadRecordedRun(personaId: string): Promise<RecordedRun | null> {
  const load = RUNS[`./runs/${personaId}.json`];
  return load ? load().catch(() => null) : Promise.resolve(null);
}

interface FittingArt {
  hero?: { src: string; score: number };
  background?: { src: string; score: number };
  icon?: { src: string; score: number };
  "icon-collection"?: { src: string; score: number };
  loop?: { src: string; score: number };
}

/** The final suite of a recorded run, in the shape the server returns for a finished job. */
export function recordedResult(personaId: string, run: RecordedRun): GenerationResult {
  // Icons shown and downloaded are the refined ones the fitting room uses; the run's scores stay.
  const raw = (fittings as Record<string, FittingArt>)[personaId] ?? {};
  const refined = fittingIcons[personaId];
  const art: FittingArt = {
    ...raw,
    ...(refined && raw.icon ? { icon: { ...raw.icon, src: refined.icon.src } } : {}),
    ...(refined && raw["icon-collection"] ? { "icon-collection": { ...raw["icon-collection"], src: refined["icon-collection"].src } } : {}),
  };
  const item = (purpose: string, a?: { src: string; score: number }) =>
    a ? [{ id: `${personaId}-${purpose}`, purpose, path: a.src, url: a.src, score: a.score }] : [];
  return {
    svgs: [...item("icon", art.icon), ...item("icon-collection", art["icon-collection"])],
    images: [...item("hero", art.hero), ...item("background", art.background)],
    videos: item("ambient-loop", art.loop),
    metadata: { generationDuration: run.durationMs, totalIterations: run.generations, coverage: new Set(run.candidates.filter((c) => c.cell).map((c) => c.cell)).size / 75 },
  };
}
